// One item per source URL. Sources, brief and limits come from the platform.
const body = $input.first().json.body || $input.first().json;
const sources = Array.isArray(body.sources) ? body.sources : String(body.sources || '').split(/\s+/).filter(Boolean);
return sources.map((url, i) => ({ json: { source_index: i, url, max_per_source: body.max_per_source || 4, lookback_hours: body.lookback_hours || 168 } }));

// Listing page -> article candidates. RSS/Atom -> <item>/<entry> links. HTML -> links under the listing path.
// n8n Cloud's Code sandbox has no URL class, so a minimal resolver is included.
function parseUrl(u) { const m = String(u).match(/^(https?:)\/\/([^\/?#]+)([^?#]*)/i); return m ? { protocol: m[1], host: m[2].toLowerCase(), pathname: m[3] || '/' } : null; }
function resolveHref(href, base) {
  href = String(href).trim();
  if (/^https?:\/\//i.test(href)) return href;
  if (href.startsWith('//')) return base.protocol + href;
  if (href.startsWith('/')) return base.protocol + '//' + base.host + href;
  if (/^(mailto:|tel:|javascript:|#)/i.test(href)) return null;
  const dir = base.pathname.replace(/[^\/]*$/, '');
  return base.protocol + '//' + base.host + dir + href;
}
// The HTTP Request node (text mode) outputs only { data }, so the source URL is recovered
// by position from "Read source list" (both nodes keep one item per source, same order).
const sourcesIn = $('Read source list').all();
const out = [];
$input.all().forEach((item, idx) => {
  const src = (sourcesIn[idx] || {}).json || {};
  const url = src.url; if (!url) return;
  const limit = src.max_per_source || 4;
  const html = String(item.json.data || '');
  if (!html) return;
  const head = html.slice(0, 600).toLowerCase();
  if (head.includes('<rss') || head.includes('<feed') || head.startsWith('<?xml')) {
    const entries = [...html.matchAll(/<(item|entry)[\s\S]*?<\/\1>/gi)].slice(0, limit);
    for (const e of entries) {
      const link = (e[0].match(/<link[^>]*>([^<]+)<\/link>/i) || e[0].match(/<link[^>]*href="([^"]+)"/i) || [,''])[1].trim();
      const title = (e[0].match(/<title[^>]*>([\s\S]*?)<\/title>/i) || [,''])[1].replace(/<!\[CDATA\[|\]\]>/g, '').trim();
      if (link) out.push({ json: { source: url, source_kind: 'rss', article_url: link, link_title: title } });
    }
    return;
  }
  const base = parseUrl(url); if (!base) return;
  const basePath = base.pathname.replace(/\/$/, '');
  const seen = new Set(); const scored = [];
  for (const m of html.matchAll(/<a[^>]+href="([^"#]+)"[^>]*>([\s\S]*?)<\/a>/gi)) {
    const href = resolveHref(m[1], base); if (!href) continue;
    const p = parseUrl(href); if (!p) continue;
    const path = p.pathname.replace(/\/$/, '');
    const title = m[2].replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
    if (p.host !== base.host || seen.has(href) || path === basePath || title.length < 15) continue;
    const under = basePath && path.startsWith(basePath + '/');
    const last = path.split('/').pop() || ''; const slugged = last.length > 20 && last.includes('-');
    if (!(under || slugged) || /\/(tags?|category|search|login|share|print|page|author)s?\//i.test(path)) continue;
    seen.add(href);
    scored.push({ score: under ? 2 : 0, json: { source: url, source_kind: 'html-listing', article_url: href, link_title: title.slice(0, 200) } });
  }
  // Links under the listing path (e.g. /en/news/<slug>) beat article-looking links elsewhere on the site.
  scored.sort((a, b) => b.score - a.score);
  let n = 0; for (const s of scored.slice(0, limit)) { out.push({ json: s.json }); n++; }
  if (n === 0) out.push({ json: { source: url, source_kind: 'html-article', article_url: url, link_title: '', data: html } });
});
return out;

// Regex-based cleaner (n8n Cloud's Code node has no HTML parser module).
function decode(s) {
  return String(s).replace(/&#(\d+);/g, (m, n) => String.fromCharCode(+n)).replace(/&#x([0-9a-f]+);/gi, (m, h) => String.fromCharCode(parseInt(h, 16)))
    .replace(/&quot;/g, '"').replace(/&#39;|&apos;/g, "'").replace(/&amp;/g, '&').replace(/&nbsp;/g, ' ')
    .replace(/&rsquo;/g, '’').replace(/&lsquo;/g, '‘').replace(/&ndash;/g, '–').replace(/&mdash;/g, '—');
}
function clean(html) {
  let h = html.replace(/<script[\s\S]*?<\/script>/gi, '').replace(/<style[\s\S]*?<\/style>/gi, '')
              .replace(/<(nav|aside|footer|header|form|iframe|noscript|svg)[\s\S]*?<\/\1>/gi, '');
  const og = (h.match(/property="og:title"[^>]*content="([^"]+)"/i) || [,''])[1];
  const title = decode((og || (h.match(/<title[^>]*>([\s\S]*?)<\/title>/i) || [,''])[1]).trim());
  const date = (h.match(/article:published_time"[^>]*content="([^"]+)"/i) || h.match(/datetime="([^"]+)"/i) || h.match(/"datePublished"\s*:\s*"([^"]+)"/) || [,''])[1] || '';
  const paras = [...h.matchAll(/<(p|h1|h2|h3|li)[^>]*>([\s\S]*?)<\/\1>/gi)]
    .map(m => decode(m[2].replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim())).filter(p => p.length > 40);
  const text = [...new Set(paras)].join('\n');
  return { title, date, text, raw_chars: html.length, clean_chars: text.length, raw_head: html.slice(0, 1500) };
}
// "Fetch article" (text mode) outputs only { data }; article_url/source/kind are recovered by
// position from "Extract articles" (one item per article, same order).
const meta = $('Extract articles').all();
return $input.all().map((item, idx) => {
  const c = clean(String(item.json.data || ''));
  const { data: _d, ...m } = ((meta[idx] || {}).json || {});
  if (!c.title) c.title = m.link_title || m.article_url;
  return { json: { ...m, ...c } };
});

// Attach the analysis to the cleaned article it belongs to (same order), keep everything for the board.
const cleaned = $('Clean HTML').all();
return $input.all().map((item, i) => { const a = cleaned[i]?.json || {}; const analysis = item.json.output || item.json; return { json: { ...a, analysis, relevant: !!analysis.relevant } }; });

