// Assemble the board: every cleaned article, with analysis, plus enrichment for the relevant ones.
const all = $('Merge analysis').all().map(i => i.json);
const enriched = $input.all().map(i => i.json.output || i.json);
const relevant = all.filter(a => a.relevant);
relevant.forEach((a, i) => { a.enriched = enriched[i] || null; });
const items = all.map(a => ({ source: a.source, source_kind: a.source_kind, url: a.article_url, title: a.title, date: a.date, raw_chars: a.raw_chars, clean_chars: a.clean_chars, raw_head: a.raw_head, text: a.text, relevant: a.relevant, analysis: a.analysis, enriched: a.enriched || null }));
const raw = items.reduce((s, i) => s + (i.raw_chars || 0), 0), cl = items.reduce((s, i) => s + (i.clean_chars || 0), 0);
return [{ json: { items, stats: { articles: items.length, relevant: relevant.length, raw_chars: raw, clean_chars: cl, removed_pct: raw ? Math.round(100 * (1 - cl / raw)) : 0 } } }];

